// LPA GO! dialogue script and Fact Bank (v0.2). Grades: Y = Convince, N = Neutral, X = Backfire.
export const CARDS = {
  'C-01': { t: `You are presumed to have capacity until it is shown otherwise. Making an unwise decision doesn't mean you lack capacity.`, s: `MCA s 3(2), 3(4); Guide Part E (Principles 1 & 3)` },
  'C-02': { t: `Capacity is decision-specific and time-specific: you can lack it for one matter and not another, or lose it and regain it. Temporary loss counts (a coma, delirium after surgery).`, s: `MCA s 4(1)–(2); Guide A1` },
  'C-03': { t: `Nobody can decide you lack capacity just from your age, appearance (features of a condition, how you're dressed), a condition (a physical or intellectual disability, an age-related illness, even being drunk), or how you behave.`, s: `MCA s 4(3); DGuide A1` },
  'C-04': { t: `The test is four abilities: understand the information, retain it, use or weigh it, and communicate the decision, by talking, signing, blinking, any means. Retaining it only briefly is still enough. Explanations must be given in a way that suits you (simple words, large print, drawings, sign language).`, s: `MCA s 5(1)–(3); Guide Part E (Principle 2)` },
  'C-05': { t: `To make an LPA you must be 21 or older and have capacity at the moment you sign. Once capacity is lost, it is too late to make one, the family must go to court instead.`, s: `MCA s 11(2)(c); Guide B; Brochure` },
  'C-06': { t: `A donee must be 21+. A personal-welfare donee must be a named individual, not "my lawyer", not a company. A property-and-affairs donee can be an individual who is not bankrupt, or a licensed trust company (property only). A lay donee cannot be paid. You yourself cannot appoint a property-and-affairs donee while you are bankrupt. The certificate issuer cannot be your family member or your donee.`, s: `MCA s 12(1)–(2); Regs reg 7(2); Guide B1, D1; DGuide C2; QRG Form 1 step 8` },
  'C-07': { t: `With two or more donees you choose: jointly (all must agree, if they can't, they can't act on that decision), or jointly and severally (any one can act). If you don't specify, the law assumes jointly. Form 1 takes up to 2 donees and 1 replacement donee, and you pick the manner once for personal welfare and once for property. A replacement donee steps in if a donee disclaims, dies, goes bankrupt (property part), divorces you, or loses capacity, and you can say which donee they replace, for which powers.`, s: `MCA s 12(4)–(9); Guide B2–B3; QRG Form 1 steps 10–18` },
  'C-08': { t: `Personal-welfare donees can decide where you live and with whom, day-to-day care (what you eat, wear, do), your social activities, your correspondence and who you have contact with. Whether they can consent to or refuse your medical treatment (including clinical trials) is a Yes/No question you answer in Form 1.`, s: `MCA s 13(6)–(7); Guide B4; QRG Form 1 step 13` },
  'C-09': { t: `Property-and-affairs donees can operate your bank accounts, pay rent, bills and the mortgage, collect income, dividends and insurance payouts, handle tax and CPF matters, invest savings, buy or sell property, and buy equipment you need.`, s: `Guide B4; DGuide C7` },
  'C-10': { t: `The LPA sleeps until it is needed. Your donee may only act when you lack capacity (or reasonably believes you do), and must step aside again if you regain it. While you can decide, you decide.`, s: `MCA s 13(1); Guide B5; DGuide D1–D2` },
  'C-11': { t: `A donee can never decide on life-sustaining treatment, or on treatment needed to prevent serious deterioration, doctors decide those in your best interests, and if you made an Advance Medical Directive the doctors must follow it. A donee also cannot make a will for you, or make/revoke CPF or insurance nominations.`, s: `MCA s 13(8), 13(9), 13(9A); Guide B5; DGuide C3, C4, C8` },
  'C-12': { t: `Some decisions nobody can make for you: marriage, sex, divorce on three years' separation, adoption, changing religion, gender-change treatment, sterilisation, abortion, organ-donation objections, an Advance Medical Directive, gifting your body, and nobody can vote for you.`, s: `MCA s 26, s 28; Guide B6; DGuide C5` },
  'C-13': { t: `"Best interests" is a legal duty: consider everything relevant, whether you'll regain capacity, involve you as much as possible, your past and present wishes (especially anything you wrote down while you had capacity), your beliefs and values, and consult the people you named and those who care for you. Your donee should also consider any Advance Care Planning you did.`, s: `MCA s 6(2)–(9); Guide Part E (Principle 4); DGuide D3` },
  'C-14': { t: `A donee can only give gifts from your money if the LPA expressly allows it. Form 1 asks you whether gifts are allowed and lets you state the value. If you allow gifts without fixing a value, they must be reasonable for the size of your estate, and your property must be preserved for your own maintenance first.`, s: `MCA s 14, s 6(7); DGuide C8 [VERIFY exact Form 1 options]` },
  'C-15': { t: `In Form 1 you can require your donee to get the court's approval before selling, transferring, mortgaging or otherwise dealing with a property, you type the property's address into the form.`, s: `QRG Form 1 step 14` },
  'C-16': { t: `Form 1 is the standard form, mostly tick-boxes granting wide powers, with basic conditions; you can complete it yourself (consult a lawyer if unsure what "wide powers" means). Form 2 has free-text spaces for specific or customised powers and must be drafted by a lawyer, who can also be your certificate issuer. Both cover personal welfare, property and affairs, or both.`, s: `Guide B; DGuide A4; QRG "Make an LPA (Form 2)"` },
  'C-17': { t: `A certificate issuer, an OPG-accredited doctor, a practising lawyer, or a psychiatrist, meets you in person after all your donees have accepted, and checks that you understand the purpose and scope of the LPA, that there is no fraud or pressure, and nothing else stops the LPA being made. You both sign digitally with the Singpass app; the CI then submits it to OPG immediately. CIs charge their own professional fee; some not-for-profits certify at affordable rates.`, s: `Regs reg 7(1); Guide D1 step 2; QRG "Certify an LPA"` },
  'C-18': { t: `LPAs are made on OPGO with Singpass, in this order: draft Form 1 → each donee and replacement donee accepts online (they get an SMS/email) → CI certifies and submits → pay if required → mandatory 3-week waiting period for objections → registered (about 8 working days on top of the 3 weeks; you get SMS updates at every stage). Since 1 April 2026 the Form 1 application fee is permanently waived for Singapore citizens; PRs, foreigners and Form 2 still pay, and the CI's fee always applies. If a donee rejects, the draft is void and you start again. Knowingly making a false statement in the application is a crime (fine up to $10,000 or 2 years' jail).`, s: `Guide D1–D2, D6, Part F; QRG steps 19–29; Brochure; Parliament 5 Mar 2026 [VERIFY fee table]` },
  'C-19': { t: `While you have capacity you can revoke your LPA any time: tell every donee in writing first, then file the notice on OPGO (a revocation fee applies); you can start drafting a new LPA while the old one is being cancelled. Nothing can be amended after submission, changing a donee means revoke-and-remake. Your bankruptcy ends the property part. A donee's appointment ends on death, bankruptcy (property part), divorce or annulment from you (unless your LPA says otherwise), formal disclaimer, or loss of capacity, and if joint donees lose one, the whole LPA fails unless a replacement or a joint-and-several donee remains.`, s: `MCA s 15; Guide B4, D5; DGuide C6, C9; QRG "Revoke LPA"` },
  'C-20': { t: `Safeguards: the Public Guardian keeps the register, receives reports, handles complaints about donees, investigates breaches, and can send a Board of Visitors member (a medically qualified Special Visitor or a General Visitor) to visit you or your donee. Since 2016 the court can suspend a donee's powers immediately if there is a risk your assets will be dissipated, and can revoke the LPA.`, s: `MCA s 31, s 35, s 36A; Guide A3` },
  'C-21': { t: `Without an LPA, your spouse and children have no automatic legal authority over your money or your care decisions. Someone must apply to the court to be your deputy: time, cost, uncertainty, and the court decides how much power to give. Deputies are unpaid unless professional, are supervised by OPG, and can't be given power to make gifts or your will.`, s: `Study 2026 p 30–32; MCA s 25(3); Brochure "True or False?"` },
  'C-22': { t: `If you have no one suitable to appoint, you can appoint a Professional Donee registered with OPG, lawyers, doctors, accountants, nurses, allied health and social work professionals who meet OPG's criteria and pass a certification course, or, for property, a licensed trust company. You agree the fee with them upfront; they must file an annual report to OPG and stay answerable to their own professional body. About 1 in 10 people intending to make an LPA now plan to.`, s: `MCA s 12(1)(a)(ii)–(iii); Guide C1–C4; Brochure; Study 2026 Fig. 9–10` },
  'C-23': { t: `Even without an LPA, doctors and carers can give care or treatment that is in your best interests if they reasonably believe you lack capacity, but they cannot act against a decision your donee made, and restraint is only allowed if necessary and proportionate.`, s: `MCA s 7, s 8; Guide A2(d); DGuide C4` },
  'C-24': { t: `Parents of a young person with an intellectual disability lose their legal say when the child turns 21. The court can appoint them deputies before 21 if the child is likely to still lack capacity; parents are preferred; another person can be named Successor Deputy. Cash assets can go into a Special Needs Trust.`, s: `MCA s 21; Guide A2(c)` },
  'C-25': { t: `An LPA is not a will (a will only speaks at death and has its own capacity test, the LPA is revoked at death and the will then takes over), not an Advance Medical Directive (a separate Act, and a donee can't make one for you), and not Advance Care Planning (non-binding wishes your donee should still consider). Do them together; they answer different questions.`, s: `MCA s 26(j); Wills Act; Brochure; DGuide D3` },
  'C-26': { t: `The numbers: about 400,000 Singapore citizens, roughly one in seven, had an LPA by early 2026. Among 49–80-year-olds, 7 in 10 have heard of it, 31% have one, 41% neither have nor intend to. Top reason for not doing it: "my children will automatically have the right" (50.8%). One in four Singaporeans will be 65+ by 2030.`, s: `Study 2026 pp 3, 5, 23, 30 [VERIFY]` },
  'C-27': { t: `An ordinary power of attorney ends when you lose capacity. The LPA is the one designed to last through it. That's the "L".`, s: `Guide B` },
  'C-28': { t: `Activating the LPA: when you lose capacity, a doctor certifies it; your donee logs into OPGO, declares that a medical practitioner has certified you lack capacity, and sends the password-protected registered LPA to the bank, hospital or agency from OPGO. Each institution may have its own extra requirements, banks follow the Association of Banks' guidelines (Aug 2026), and may ask for a doctor's certificate that your incapacity is likely to be permanent.`, s: `Guide D1 step 3, D3; DGuide A4; QRG "View and Send LPA"; MCA s 13(10) [VERIFY ABS guidelines]` },
  'C-29': { t: `Donees are accountable: they must keep records (and accounts, for property), keep your money separate from theirs, act only within the LPA, and cannot hand their authority to anyone else. The Public Guardian can require reports or information and investigate complaints; the court can call for a Board of Visitors report.`, s: `MCA s 31(1)(f); Regs regs 31–33, 38; DGuide C3, C8` },
  'C-30': { t: `Singapore's law expects family to be the first line of support, but "family first" only works if the law knows which family member you chose. Singles and childless couples increasingly need friends or professionals as donees.`, s: `Study 2026 p 31; Guide C1` },
  'C-31': { t: `Five statutory principles everyone acting for you must follow: (1) presume capacity; (2) give all practicable help before concluding someone can't decide; (3) an unwise decision is not incapacity; (4) act in the person's best interests; (5) choose the less restrictive option, sometimes that means doing nothing.`, s: `MCA s 3; Guide Part E; DGuide D4` },
  'C-32': { t: `A donee's dos and don'ts: follow the statutory principles and the Code of Practice; act in good faith, with reasonable care and skill; respect confidentiality; keep records (and accounts, for property); don't benefit yourself; don't pass your authority to anyone else; don't give up the role without telling the donor and OPG.`, s: `DGuide C3, C8` },
  'C-33': { t: `After your LPA is registered: you and your donees can view and download it on OPGO any time. Tell the people your donee will one day deal with, your doctor, your bank, the CPF Board, insurers, CDP or your broker, that you've made an LPA and ask what they'll need. Anyone with a good reason can search the register or request a certified copy for a small fee.`, s: `Guide D3; QRG "View and Send", "Search Request", "CTC Application"` },
  'C-34': { t: `If your donees disagree with each other, or with a doctor: hold a best-interests meeting; get a second opinion; try mediation (Community Mediation Centre, Singapore Mediation Centre); ask a Family Service Centre for help. Court is the last resort.`, s: `DGuide Part E (Halimah's story)` },
  'C-35': { t: `Form 1 limits: up to 2 donees + 1 replacement donee; one manner of acting for personal welfare and one for property; a trust company can be a property donee only; a replacement can be assigned to a specific donee and specific powers. Anything finer, more donees, split rules within property, standing instructions, is Form 2.`, s: `QRG Form 1 steps 10–18, Form 2 step 10; Guide B2` },
  'C-36': { t: `Your donee is protected too: a donee who acts in good faith under the LPA is not liable just because it later turns out the power didn't exist or had ended, unless they knew. Being asked is not being set up.`, s: `DGuide C12; MCA s 13` }
};

